#!/bin/bash
set -e
cd "C:/Yati website/src/assets/products"

dl() {
  curl -sL -o "$2" "$1"
  sz=$(stat -c%s "$2" 2>/dev/null || echo '?')
  echo "$2 -> $sz bytes"
}

